#!/usr/bin/env bash
# =================================================================
#  SOZIP LAUNCHER - Linux installer (self-contained, plain bash)
#  Downloads launcher.appimage into a folder you choose and wires
#  up menu / desktop entries. Uninstall = delete the folder.
# =================================================================
set -euo pipefail

APP_NAME="SOZIP LAUNCHER"
EXE_NAME="launcher.appimage"
DESKTOP_ID="sozip-launcher.desktop"
URL="${SOZIP_URL:-https://github.com/sozipp/sozip-launcher/releases/latest/download/launcher.appimage}"
MIN_BYTES=1048576   # sanity: release must be at least 1 MB

ICON_B64=''

# ---------------- UI plumbing -------------------------------------
have() { command -v "$1" >/dev/null 2>&1; }

GUI_MODE=0
if [ "${SOZIP_TUI:-0}" = "1" ]; then
  GUI_MODE=0
elif [ -t 0 ]; then
  GUI_MODE=0
elif have zenity; then
  GUI_MODE=1
else
  echo "SOZIP LAUNCHER installer: please run me from a terminal (or install 'zenity')." >&2
  exit 1
fi

if [ "$GUI_MODE" -eq 0 ] && [ -t 1 ]; then
  BOLD=$'\033[1m'; DIM=$'\033[2m'; RESET=$'\033[0m'
  PURPLE=$'\033[38;5;141m'; GREEN=$'\033[38;5;114m'
  RED=$'\033[38;5;203m'; YELLOW=$'\033[38;5;179m'
else
  BOLD=""; DIM=""; RESET=""; PURPLE=""; GREEN=""; RED=""; YELLOW=""
fi

ui_info()  { if [ "$GUI_MODE" -eq 1 ]; then zenity --info --width=460 --title="$APP_NAME Installer" --text="$1" >/dev/null 2>&1 || true; else printf '%s\n' "$1"; fi; }
ui_error() { if [ "$GUI_MODE" -eq 1 ]; then zenity --error --width=420 --title="$APP_NAME Installer" --text="$1" >/dev/null 2>&1 || true; else printf '%s%s%s\n' "$RED" "$1" "$RESET" >&2; fi; }
die()      { ui_error "$1"; exit 1; }

ui_warn() {
  if [ "$GUI_MODE" -eq 1 ]; then
    zenity --warning --width=420 --title="$APP_NAME Installer" --text="$1" >/dev/null 2>&1 || true
  else
    printf '%s  %s! %s%s\n' "$YELLOW" "WARNING" "$1" "$RESET"
  fi
}

ui_confirm() { # $1 = question, $2 = default y|n ; returns 0 on yes
  local q="$1" def="${2:-y}" a=""
  if [ "$GUI_MODE" -eq 1 ]; then
    if [ "$def" = "y" ]; then
      zenity --question --width=420 --title="$APP_NAME Installer" --text="$q" >/dev/null 2>&1
    else
      zenity --question --width=420 --title="$APP_NAME Installer" --text="$q (recommended: No)" >/dev/null 2>&1
    fi
  else
    while :; do
      if [ "$def" = "y" ]; then printf '  %s [Y/n]: ' "$q"; else printf '  %s [y/N]: ' "$q"; fi
      if ! IFS= read -r a; then
        # input closed (EOF): treat as explicit "no"
        return 1
      fi
      a="${a,,}"
      [ -z "$a" ] && a="$def"
      case "$a" in
        y|yes) return 0 ;;
        n|no)  return 1 ;;
      esac
      printf '  Please answer y or n.\n'
    done
  fi
}

ui_pick_dir() { # prints chosen raw path; non-zero rc = cancelled
  if [ "$GUI_MODE" -eq 1 ]; then
    zenity --file-selection --directory --title="Choose an EMPTY folder for $APP_NAME"
  else
    local d=""
    printf '\n%s[1/5]%s Choose where to install %s\n' "$BOLD" "$RESET" "$APP_NAME" >&2
    printf '%s  Everything stays inside the folder you select.%s\n' "$DIM" "$RESET" >&2
    printf '  Type a folder path and press Enter.\n' >&2
    printf '  Type %sgui%s and press Enter to pick the folder in your file manager.\n' "$BOLD" "$RESET" >&2
    printf '  Folder [%s]: ' "${HOME}/SOZIP-Launcher" >&2
    if ! IFS= read -r d; then
      printf '\n'
      return 4
    fi
    printf '%s' "$d"
  fi
}

banner() {
  cat <<'ART'

 ____    ___   _____  ___    ____
/ ___|  / _ \ |__  / |_ _|  |  _ \
\___ \ | | | |  / /   | |   | |_) |
 ___) || |_| | / /_   | |   |  __/
|____/  \___/ /____| |___|  |_|

 _         /\    _   _  _ __    ____  _   _  _____  ____
| |       /  \  | | | || '_ \  / ___|| | | || ____||  _ \
| |      / /\ \ | | | || | | || |    | |_| ||  _|  | |_) |
| |___  / ____ \| |_| || | | || |___ |  _  || |___ |  _ <
|_____|/_/    \_\ \___/|_| |_| \____||_| |_||_____||_| \_\

        I N S T A L L E R   -   free & open source

ART
}

step() { [ "$GUI_MODE" -eq 0 ] && printf '%s[%s]%s %s\n' "$BOLD" "$1" "$RESET" "$2"; }
okln() { [ "$GUI_MODE" -eq 0 ] && printf '%s     OK:%s %s\n' "$GREEN" "$RESET" "$1"; }

trap 'printf "\nCancelled.\n"; exit 130' INT TERM

# ---------------- helpers -----------------------------------------
normalize_dir() {
  local d="$1"
  d="${d#"${d%%[![:space:]]*}"}"   # ltrim
  d="${d%"${d##*[![:space:]]}"}"   # rtrim
  d="${d%\"}" ; d="${d#\"}"
  d="${d%/}"
  case "$d" in "~") d="$HOME" ;; "~/"*) d="$HOME/${d#\~/}" ;; esac
  printf '%s' "$d"
}

valid_new_dir() { # returns 0 when usable; may create it
  local d="$1"
  [ -z "$d" ] && { ui_warn "Please enter a folder path."; return 1; }
  case "$d" in *'"'*|*'*'*|*$'\n'*|*'`'*) ui_warn "That path contains characters I cannot use."; return 1 ;; esac
  if [ -e "$d" ] && [ ! -d "$d" ]; then ui_warn "That path is a file, not a folder."; return 1; fi
  if [ -d "$d" ] && [ -n "$(ls -A -- "$d" 2>/dev/null)" ]; then
    ui_warn "'$d' is not empty. SOZIP needs a fresh empty folder."
    return 1
  fi
  if [ ! -d "$d" ]; then
    mkdir -p -- "$d" 2>/dev/null || { ui_warn "Cannot create folder '$d' (permission denied?)."; return 1; }
  fi
  if ! touch -- "$d/.sozip-write-test" 2>/dev/null; then
    ui_warn "No write permission inside '$d'. Pick somewhere writable."
    return 1
  fi
  rm -f -- "$d/.sozip-write-test"
  return 0
}

download_file() { # $1=url $2=out
  local url="$1" out="$2"
  local part="$out.part" pid rc
  rm -f -- "$part"
  if [ "$GUI_MODE" -eq 1 ]; then
    (
      if have curl; then exec curl -fsSL --retry 3 --retry-delay 2 -o "$part" "$url"
      else exec wget -q -O "$part" "$url"; fi
    ) &
    pid=$!
    {
      while kill -0 "$pid" 2>/dev/null; do
        printf '#Downloading %s... (%s)\n' "$APP_NAME" "$(du -h "$part" 2>/dev/null | cut -f1)"
        sleep 0.4
      done
    } | zenity --progress --pulsate --auto-close --no-cancel --width=460 \
          --title="$APP_NAME Installer" >/dev/null 2>&1 || true
    if kill -0 "$pid" 2>/dev/null; then
      kill "$pid" 2>/dev/null || true
      wait "$pid" 2>/dev/null || true
      die "Download cancelled."
    fi
    wait "$pid" || die "Download failed. Check your internet connection."
  else
    step "2/5" "Downloading SOZIP LAUNCHER from GitHub..."
    if have curl; then
      curl -fL --retry 3 --retry-delay 2 --progress-bar -o "$part" "$url" || \
        die "Download failed. Check your internet connection and try again."
    elif have wget; then
      wget -q --show-progress -O "$part" "$url" || \
        die "Download failed. Check your internet connection and try again."
    else
      die "Neither 'curl' nor 'wget' was found. Install one of them and re-run."
    fi
  fi
  local size
  size=$(stat -c%s -- "$part" 2>/dev/null || echo 0)
  [ "$size" -ge "$MIN_BYTES" ] || { rm -f -- "$part"; die "Download failed (file too small). Try again."; }
  mv -f -- "$part" "$out"
}

apps_dir() {
  local ad="${XDG_DATA_HOME:-$HOME/.local/share}/applications"
  mkdir -p -- "$ad"
  printf '%s' "$ad"
}

desktop_dir() {
  local conf="${XDG_CONFIG_HOME:-$HOME/.config}/user-dirs.dirs" dd=""
  if [ -r "$conf" ]; then
    dd=$(grep -m1 '^XDG_DESKTOP_DIR=' "$conf" 2>/dev/null | cut -d= -f2- \
         | sed -e 's/^[[:space:]]*//' -e 's/^"//' -e 's/"$//' -e "s|\$HOME|$HOME|g")
  fi
  [ -z "$dd" ] && dd="$HOME/Desktop"
  mkdir -p -- "$dd" 2>/dev/null || true
  printf '%s' "$dd"
}

write_desktop() { # $1 = destination file, $2 = dir, $3 = desktop path or ""
  local dst="$1" dir="$2"
  cat > "$dst" <<EOF
[Desktop Entry]
Type=Application
Version=1.0
Name=$APP_NAME
GenericName=Minecraft Launcher
Comment=Free & open source Minecraft launcher - everything in one folder
Exec="$dir/$EXE_NAME"
Path=$dir
TryExec=$dir/$EXE_NAME
Icon=$ICON_PATH
Terminal=false
Categories=Game;
StartupNotify=true
EOF
}

# ---------------- main --------------------------------------------
[ "$GUI_MODE" -eq 0 ] && { clear >/dev/null 2>&1 || true; }
if [ "$GUI_MODE" -eq 0 ]; then
  printf '%s%s%s\n' "$PURPLE" "$(banner)" "$RESET"
  printf '  Hi! This will install the free & open source %s.\n\n' "$BOLD$APP_NAME$RESET"
fi

DIR=""
while :; do
  RAW="$(ui_pick_dir)" || die "Cancelled."
  if [ "$GUI_MODE" -eq 1 ] && [ -z "$RAW" ]; then die "Cancelled."; fi
  case "${RAW,,}" in
    gui)
      if ! have zenity; then
        ui_warn "The file-manager picker needs 'zenity'. Please type a folder path instead."
        continue
      fi
      RAW="$(zenity --file-selection --directory --title="Choose an EMPTY folder for $APP_NAME")" || continue
      [ -z "$RAW" ] && continue
      ;;
    "")
      [ "$GUI_MODE" -eq 0 ] && RAW="${HOME}/SOZIP-Launcher"
      ;;
  esac
  DIR="$(normalize_dir "$RAW")"
  valid_new_dir "$DIR" && break
done
DIR="$(realpath -m -- "$DIR" 2>/dev/null || printf '%s' "$DIR")"
okln "Install folder: $DIR"

download_file "$URL" "$DIR/$EXE_NAME"
chmod +x -- "$DIR/$EXE_NAME"
okln "Downloaded $EXE_NAME ($(du -h "$DIR/$EXE_NAME" | cut -f1))"

step "3/5" "Preparing the SOZIP icon..."
ICON_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/sozip-launcher"
ICON_PATH="$ICON_DIR/sozip_icon.png"
mkdir -p -- "$ICON_DIR"
printf '%s' "$ICON_B64" | base64 -d > "$ICON_PATH" 2>/dev/null \
  || die "Failed to write icon file."
okln "Icon installed (kept outside your game folder)."

APPS="$(apps_dir)"
DESK="$(desktop_dir)"

step "4/5" "Shortcuts..."
WANT_MENU=0; WANT_DESK=0
if ui_confirm "Add ${APP_NAME} to the app menu? (makes it searchable)"; then
  WANT_MENU=1
  write_desktop "$APPS/$DESKTOP_ID" "$DIR"
  update-desktop-database "$APPS" 2>/dev/null || true
  okln "Menu entry added."
else
  okln "Skipped menu entry."
fi
if ui_confirm "Create a desktop shortcut?"; then
  WANT_DESK=1
  write_desktop "$DESK/$DESKTOP_ID" "$DIR"
  gio set "$DESK/$DESKTOP_ID" metadata::trusted true 2>/dev/null || true
  chmod +x "$DESK/$DESKTOP_ID" 2>/dev/null || true
  okln "Desktop shortcut created."
else
  okln "Skipped desktop shortcut."
fi

step "5/5" "Writing uninstaller..."
cat > "$DIR/uninstall-sozip.sh" <<UNINST
#!/usr/bin/env bash
# Removes SOZIP LAUNCHER installed at: $DIR
set -u
rm -f "\${XDG_DATA_HOME:-\$HOME/.local/share}/applications/$DESKTOP_ID"
rm -f "$DESK/$DESKTOP_ID"
rm -rf -- "$ICON_DIR"
update-desktop-database "\${XDG_DATA_HOME:-\$HOME/.local/share}/applications" 2>/dev/null
cd /
rm -rf -- "$DIR"
echo "SOZIP LAUNCHER removed."
UNINST
chmod +x "$DIR/uninstall-sozip.sh"
okln "uninstall-sozip.sh written."

echo ""
if [ "$GUI_MODE" -eq 1 ]; then
  zenity --info --width=480 --title="$APP_NAME Installer" \
    --text="<b>Installed!</b>\n\nFolder: $DIR\nMenu entry: $( [ "$WANT_MENU" -eq 1 ] && echo yes || echo no )   Desktop shortcut: $( [ "$WANT_DESK" -eq 1 ] && echo yes || echo no )\n\nTo uninstall later: delete the folder,\nor run uninstall-sozip.sh inside it." \
    >/dev/null 2>&1 || true
else
  printf '%s----------------------------------------------------------%s\n' "$PURPLE" "$RESET"
  printf '  %s%s installed successfully!%s\n' "$GREEN$BOLD" "$APP_NAME" "$RESET"
  printf '  Folder      : %s\n' "$DIR"
  printf '  Menu entry  : %s\n' "$( [ "$WANT_MENU" -eq 1 ] && echo yes || echo no )"
  printf '  Desktop icon: %s\n' "$( [ "$WANT_DESK" -eq 1 ] && echo yes || echo no )"
  printf '  Uninstall   : delete that folder, or run its uninstall script.\n'
  printf '%s----------------------------------------------------------%s\n' "$PURPLE" "$RESET"
fi

if ui_confirm "Launch ${APP_NAME} now?"; then
  ( cd "$DIR" && nohup "./$EXE_NAME" >/dev/null 2>&1 & )
  [ "$GUI_MODE" -eq 0 ] && printf '  Starting %s...\n' "$APP_NAME"
fi

if [ "$GUI_MODE" -eq 0 ]; then
  printf '%s  Tip:%s if the AppImage ever fails to open, install libfuse2\n  (e.g. sudo apt install libfuse2).\n\n' "$YELLOW" "$RESET"
fi